using System;using System.IO;using System.Collections;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;using UnityEngine;using UnityEngine.UI;using UnityEngine.SceneManagement;using UnityEngine.TestTools;
namespace IdleIntelligence.PlayTests
{
 public sealed class StoryUITests
 {
  void OpenMenuRoute(string route){game.GetComponent<IdleIntelligence.Runtime.GameMenu>().Open();Click("Menu-"+route);}


  string dir;GameRuntime game;static void Click(string name){var b=GameObject.Find(name)?.GetComponent<Button>();Assert.That(b,Is.Not.Null,name);Assert.That(b.interactable,Is.True,name);b.onClick.Invoke();}
  [UnitySetUp]public IEnumerator Setup(){dir=Path.Combine(Path.GetTempPath(),"unity-story-ui-"+Guid.NewGuid());Directory.CreateDirectory(dir);GameRuntime.SavePathOverride=Path.Combine(dir,"save.json");yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();}
  [UnityTearDown]public IEnumerator Cleanup(){if(game!=null)UnityEngine.Object.Destroy(game.gameObject);yield return null;GameRuntime.SavePathOverride=null;Directory.Delete(dir,true);}
  [UnityTest]public IEnumerator MiraActuallyOpensAndCostDetailsAreReachableWithoutPurchasing(){yield return null;Assert.That(GameObject.Find("AutomaticMira"),Is.Not.Null,"Naming must be presented in the real scene");Assert.That(GameObject.Find("MiraCompanyMilestone"),Is.Null,"Later Company information must not displace first-run naming");GameObject.Find("StoryNameInput").GetComponent<InputField>().text="AURA";Click("StoryChooseName");for(int i=0;i<30&&(game.State.Story.target=="prologue"||game.State.Story.open=="tutorial-tap");i++){yield return null;Click("StoryContinue");}yield return null;Assert.That(GameObject.Find("AutomaticMira"),Is.Not.Null,"Non-modal guide remains available");Click("TrainingTab");yield return null;var before=game.State.Credits;Click("Details-training-quality");yield return null;Assert.That(GameObject.Find("EconomyDetailFacts").GetComponent<Text>().text,Does.Contain(Game.TrainingWork(game.State,"quality").ToString("F2")));Assert.That(game.State.Training,Is.Null);Assert.That(game.State.Credits.CompareTo(before),Is.Zero);Click("CloseEconomyDetail");yield return null;Click("ResearchTab");yield return null;Click("Details-research-dataGeneration");yield return null;Assert.That(GameObject.Find("EconomyDetailFacts").GetComponent<Text>().text,Is.Not.Empty);Assert.That(game.State.ResearchJob,Is.Null);WorkshopTests.Capture(320,568,"/tmp/unity-economy-details-320.png");}
  [UnityTest]public IEnumerator ActualMiraNamePrologueSkipResumeAndSavedEventSurviveReload(){Click("ResearchTab");yield return null;OpenMenuRoute("story");yield return null;GameObject.Find("StoryNameInput").GetComponent<InputField>().text="AURA";Click("StoryChooseName");Assert.That(game.State.Retention.aiName,Is.EqualTo("AURA"));for(int i=0;i<30&&(game.State.Story.target=="prologue"||game.State.Story.open=="tutorial-tap");i++){yield return null;Click("StoryContinue");}Assert.That(game.State.Story.target,Is.EqualTo("tap"));Click("StoryShowTarget");yield return null;Click("TapLab");Click("hardware-calculator");Assert.That(game.State.Story.target,Is.EqualTo("training"));game.Show("story");yield return null;Click("StoryEndGuide");Assert.That(Game.IntroQuality(game.State),Is.False);Click("StoryResume");Assert.That(Game.IntroQuality(game.State),Is.True);Click("StoryShowTarget");yield return null;Click("training-quality");Assert.That(game.State.Journal.Has("training-start"),Is.True);Assert.That(game.State.Story.target,Is.EqualTo("research"));game.Show("story");yield return null;foreach(int width in new[]{320,390,430})WorkshopTests.Capture(width,width==320?568:width==390?844:932,"/tmp/unity-story-actual-"+width+".png");yield return SceneManager.LoadSceneAsync("IdleIntelligence");yield return null;game=UnityEngine.Object.FindFirstObjectByType<GameRuntime>();Assert.That(game.State.Retention.aiName,Is.EqualTo("AURA"));Assert.That(game.State.Journal.Has("training-start"),Is.True);Assert.That(game.State.Story.target,Is.EqualTo("research"));game.Show("story");yield return null;Assert.That(GameObject.Find("StoryDialogue").GetComponent<Text>().text,Is.Not.Empty);}
 }
}
